const _kbStr=(v,max=4000)=>typeof v==='string'?v.slice(0,max):(v==null?'':String(v).slice(0,max));
// Explicit key skip: a crafted "__proto__"/"constructor"/"prototype" own-key in parsed
// JSON must never reach a spread/assign path. (Copies onto a plain object literal; the
// key skip is what does the work.)
const _kbSafeKeys=o=>{const out={};for(const k of Object.keys(o||{})){if(k==='__proto__'||k==='constructor'||k==='prototype')continue;out[k]=o[k];}return out;};
function kbNormalizeImported(raw){
  if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('This file is not a LATTE Knowledge Base object.');
  const src=_kbSafeKeys(raw);
  if(!Array.isArray(src.conditions))throw new Error('This JSON does not contain a LATTE Knowledge Base (no conditions array).');
  const dropped={conditions:0,facts:0};
  const conditions=[];
  for(const c0 of src.conditions.slice(0,2000)){
    if(!c0||typeof c0!=='object'||Array.isArray(c0)){dropped.conditions++;continue;}
    const c=_kbSafeKeys(c0);
    const name=_kbStr(c.name,300).trim();
    if(!name){dropped.conditions++;continue;}
    const facts=[];
    for(const f0 of (Array.isArray(c.facts)?c.facts:[]).slice(0,5000)){
      if(!f0||typeof f0!=='object'||Array.isArray(f0)){dropped.facts++;continue;}
      const f=_kbSafeKeys(f0);
      const text=_kbStr(f.text).trim();
      if(!text){dropped.facts++;continue;}
      const tier=[1,2,3].includes(Number(f.tier))?Number(f.tier):3;
      facts.push({
        id:_kbStr(f.id,60)||'',
        text,tier,
        latteBucket:KB_BUCKETS.includes(f.latteBucket)?f.latteBucket:'Look',
        subtype:f.subtype==null?null:_kbStr(f.subtype,60),
        factType:_kbStr(f.factType,60)||'other',
        safetyCritical:!!f.safetyCritical,
        recovered:!!f.recovered,
        sourceQuote:_kbStr(f.sourceQuote,600),
        sources:Array.isArray(f.sources)?f.sources.slice(0,50).filter(s=>s&&typeof s==='object').map(s=>{const x=_kbSafeKeys(s);return{filename:_kbStr(x.filename,300),location:_kbStr(x.location,300)};}):[],
      });
    }
    // v15.14: was dropped.conditions++, which counted a condition the loop then KEPT.
    if(!Array.isArray(c.facts)&&c.facts!=null)dropped.facts++;
    conditions.push({id:_kbStr(c.id,80)||kbSlug(name),name,aliases:Array.isArray(c.aliases)?c.aliases.slice(0,50).map(a=>_kbStr(a,200)).filter(Boolean):[],facts});
  }
  if(!conditions.length)throw new Error('No usable conditions were found in this file.');
  // Re-key fact ids so downstream fact-id diffing (Anki coverage) stays sound even if
  // the imported file had duplicates, gaps, or none at all.
  let n=0;for(const c of conditions)for(const f of c.facts)f.id='fact-'+(++n);
  // v15.14: and the same for condition ids, which an imported file is free to duplicate or
  // omit. They are React keys and the selection handle, so a collision makes one condition
  // unreachable in the UI.
  const seenCondIds=new Set();
  for(const c of conditions){let id=c.id,k=2;while(seenCondIds.has(id))id=c.id+'-'+(k++);seenCondIds.add(id);c.id=id;}
  const meta=_kbSafeKeys(src.metadata||{});
  // v15: side arrays (medications, diagnostics, …) now get the same proto-key strip as
  // conditions/facts — they enter state and IndexedDB, so sanitize before they grow a UI.
  const arr=k=>Array.isArray(src[k])?src[k].slice(0,5000).map(x=>x&&typeof x==='object'&&!Array.isArray(x)?_kbSafeKeys(x):x):[];
  return {kb:{
    metadata:{course:_kbStr(meta.course,300),exam:_kbStr(meta.exam,300),createdAt:_kbStr(meta.createdAt,80),schemaVersion:_kbStr(meta.schemaVersion,20)||'1.1'},
    sources:Array.isArray(src.sources)?src.sources.slice(0,500):[],
