}
// ── Durable Knowledge Base persistence (IndexedDB; localStorage is migration fallback only) ──
const KB_DB_NAME='latte-study-suite';
const KB_DB_VERSION=1;
const KB_DB_STORE='knowledge';
const KB_DB_KEY='active';
function kbOpenDB(){
  return new Promise((resolve,reject)=>{
    if(!('indexedDB' in window))return reject(new Error('IndexedDB is unavailable in this browser.'));
    const req=indexedDB.open(KB_DB_NAME,KB_DB_VERSION);
    req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(KB_DB_STORE))db.createObjectStore(KB_DB_STORE);};
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error||new Error('Could not open IndexedDB.'));
  });
}
// v15.14: one transaction runner, so every path settles AND closes.
// Three defects, all in the same shape. kbLoadPersisted resolved inside req.onsuccess —
// ahead of tx.oncomplete — and never called db.close() on the req.onerror path. And none of
// the three handled tx.onabort, which is the one that matters: an aborted transaction left
// the promise PENDING FOREVER. That is not a leak, it is a silent functional failure. App's
// load effect awaits kbLoadPersisted, so it never reaches setPersistenceStatus('ready') or
// 'fallback'; persistenceStatus stays 'loading'; and the save effect early-returns on
// 'loading'. The Knowledge Base then quietly stops persisting for the rest of the session,
// with no error anywhere, and the user finds out on reload.
function kbRunTx(db,mode,body){
  return new Promise((resolve,reject)=>{
    let tx,result=null;
    const settle=fn=>()=>{try{db.close();}catch(e){}fn();};
    try{tx=db.transaction(KB_DB_STORE,mode);}
    catch(e){try{db.close();}catch(e2){}return reject(e);}
    tx.oncomplete=settle(()=>resolve(result));
    tx.onerror=settle(()=>reject(tx.error||new Error('IndexedDB transaction failed.')));
    tx.onabort=settle(()=>reject(tx.error||new Error('IndexedDB transaction aborted.')));
    // A synchronous throw here (a non-cloneable value reaching put, a missing store) would
    // otherwise escape before any handler is armed, leaving the promise pending.
    try{body(tx.objectStore(KB_DB_STORE),v=>{result=v;});}
    catch(e){try{tx.abort();}catch(e2){}}
  });
}
// v15.17: raw KB and save metadata commit together; imported createdAt never orders saves.
const KB_META_KEY='active-save-v2',KB_FALLBACK_KEY='latte_knowledge_snapshot_v2',KB_LEGACY_KEY='latte_knowledge_base_v1';
function kbStoredRecord(kb,meta=null){
  if(!kb&& !meta?.deleted)return null;
  const bytes=JSON.stringify(kb||null);
  return {kb:kb||null,meta:meta?.bytes===bytes?meta:null};
}
function kbStoredKey(record){return record?.meta?JSON.stringify([record.meta.writer,record.meta.sequence]):JSON.stringify(record?.kb||null);}
async function kbLoadPersisted(){
  const db=await kbOpenDB();
  return kbRunTx(db,'readonly',(store,set)=>{
    let kb=null,meta=null;const publish=()=>set(kbStoredRecord(kb,meta));
    const a=store.get(KB_DB_KEY),b=store.get(KB_META_KEY);
    a.onsuccess=()=>{kb=a.result||null;publish();};b.onsuccess=()=>{meta=b.result||null;publish();};
  });
}
async function kbSavePersisted(record,expected=null){
  const db=await kbOpenDB();
  const result=await kbRunTx(db,'readwrite',(store,set)=>{
    let kb=null,meta=null,n=0;const commit=()=>{
      if(++n!==2)return;const actual=kbStoredRecord(kb,meta);
      if(kbStoredKey(actual)!==kbStoredKey(expected)){set({conflict:true,actual});return;}
      if(record.kb)store.put(record.kb,KB_DB_KEY);else store.delete(KB_DB_KEY);
      store.put(record.meta,KB_META_KEY);set({saved:true});
    };
    const a=store.get(KB_DB_KEY),b=store.get(KB_META_KEY);
    a.onsuccess=()=>{kb=a.result||null;commit();};b.onsuccess=()=>{meta=b.result||null;commit();};
  });
