async function kbDeletePersisted(record,expected=null){
  // An ordered tombstone prevents an older fallback from resurrecting a cleared KB.
  return kbSavePersisted({...record,kb:null,meta:{...record.meta,deleted:true,bytes:'null'}},expected);
}
function kbReconcileStored(records){
  const choices=[];
  for(const record of records.filter(Boolean)){
    const same=choices.find(x=>JSON.stringify(x.kb)===JSON.stringify(record.kb));
    if(same){if(!same.meta&&record.meta){same.meta=record.meta;}continue;}
    choices.push({...record});
  }
  if(choices.length<2)return {record:choices[0]||null,choices:[]};
  // Only metadata written by this app within one writer lineage orders snapshots.
  const newest=choices.find(x=>x.meta&&choices.every(y=>y===x||y.meta&&y.meta.writer===x.meta.writer&&y.meta.sequence<x.meta.sequence||x.meta.parent===kbStoredKey(y)));
