}
function kbReadFallbacks(){
  const records=[];
  for(const key of [KB_FALLBACK_KEY,KB_LEGACY_KEY]){
    const raw=localStorage.getItem(key);if(!raw)continue;
    let parsed;try{parsed=JSON.parse(raw);}catch{throw new Error('A saved Knowledge Base could not be read. Existing browser data was preserved.');}
    if(key===KB_FALLBACK_KEY&&(!parsed||!Object.hasOwn(parsed,'kb')||!parsed.meta||parsed.meta.bytes!==JSON.stringify(parsed.kb)))throw new Error('Saved fallback metadata is invalid. Existing browser data was preserved.');
    records.push(key===KB_FALLBACK_KEY?kbStoredRecord(parsed.kb,parsed.meta):kbStoredRecord(parsed));
