}
function kbClearFallbacks(captured){
  for(const key of [KB_FALLBACK_KEY,KB_LEGACY_KEY])if(localStorage.getItem(key)===captured[key])localStorage.removeItem(key);
}
function kbCaptureFallbacks(){return Object.fromEntries([KB_FALLBACK_KEY,KB_LEGACY_KEY].map(key=>[key,localStorage.getItem(key)]));}
async function kbArchiveRecovery(records){
  // Preserve both candidates before a recovery choice may overwrite either active store.
  const key='recovery-'+Date.now()+'-'+Math.random().toString(36).slice(2);
  try{const db=await kbOpenDB();await kbRunTx(db,'readwrite',store=>store.put(records,key));}
  catch(e){localStorage.setItem('latte_'+key,JSON.stringify(records));}
