function kbCreateSaveQueue({write,remove,writeFallback,captureFallbacks,clearFallbacks,writer}){
  let tail=Promise.resolve(),sequence=0,head=null,blocked=false,acceptedFallbacks;
  const conflict=()=>{blocked=true;return Object.assign(new Error('Another browser changed the fallback Knowledge Base. Both existing data and this in-memory snapshot are preserved; export and reload to reconcile.'),{name:'KBConflict'});};
  return {
    setHead(record,fallbacks){head=record;acceptedFallbacks=fallbacks;},
    save(kb){
      const n=++sequence,copy=kb?JSON.parse(JSON.stringify(kb)):null;
      const job=async()=>{
        if(blocked)throw new Error('Saving paused after a storage conflict. Export and reload to reconcile.');
