function validateLatteKnowledgeBase(kb){
  const issues=[];
  const buckets=new Set(['BriefPatho','Look','Assess','Tests','Treatments','Educate']);
  const ids=new Set();
  for(const c of kb.conditions||[]){
    if(!String(c.name||'').trim())issues.push({severity:'error',message:'A condition is missing its name.'});
    if(!(c.facts||[]).length)issues.push({severity:'warning',condition:c.name,message:'Condition has no extracted facts.'});
    for(const f of c.facts||[]){
      if(ids.has(f.id))issues.push({severity:'error',condition:c.name,factId:f.id,message:'Duplicate fact ID.'});
      ids.add(f.id);
      if(!buckets.has(f.latteBucket))issues.push({severity:'error',condition:c.name,factId:f.id,message:'Invalid LATTE bucket: '+String(f.latteBucket)});
      if(![1,2,3].includes(Number(f.tier)))issues.push({severity:'error',condition:c.name,factId:f.id,message:'Fact does not have exactly one valid tier.'});
      if(!String(f.text||'').trim())issues.push({severity:'error',condition:c.name,factId:f.id,message:'Fact text is empty.'});
