function _pptxRunText(xml) {
  const doc = new DOMParser().parseFromString(xml, 'application/xml');
  let runs = doc.getElementsByTagNameNS(_OOXML_A_NS, 't');
  if (!runs || !runs.length) runs = doc.getElementsByTagName('a:t');
  const out = [];
  for (let i = 0; i < runs.length; i++) {
    const t = runs[i].textContent;
    if (t && t.trim()) out.push(t.trim());
  }
  return out;
}
function _zipNormalizePath(basePath,target){
  const base=basePath.split('/');base.pop();
  for(const part of String(target||'').replace(/\\/g,'/').split('/')){
    if(!part||part==='.')continue;
    if(part==='..')base.pop();else base.push(part);
  }
  return base.join('/').replace(/^\//,'');
}
function _xmlElementsByLocalName(doc,name){
  return Array.from(doc.getElementsByTagName('*')).filter(el=>el.localName===name||el.nodeName.split(':').pop()===name);
}
function _relsMap(xml){
  const doc=new DOMParser().parseFromString(xml,'application/xml');const map=new Map();
  for(const rel of _xmlElementsByLocalName(doc,'Relationship'))map.set(rel.getAttribute('Id'),{target:rel.getAttribute('Target')||'',type:rel.getAttribute('Type')||''});
  return map;
}
async function extractPptxText(file) {
  if (typeof JSZip === 'undefined') throw new Error('JSZip failed to load — cannot read PPTX. Convert the deck to PDF and re-upload.');
  const zip = await JSZip.loadAsync(file);
  let slides=[];
  // PowerPoint presentation order is defined by presentation.xml relationships, not slide filenames.
  if(zip.files['ppt/presentation.xml']&&zip.files['ppt/_rels/presentation.xml.rels']){
    const presXml=await zip.files['ppt/presentation.xml'].async('string');
    const presDoc=new DOMParser().parseFromString(presXml,'application/xml');
    const rels=_relsMap(await zip.files['ppt/_rels/presentation.xml.rels'].async('string'));
    slides=_xmlElementsByLocalName(presDoc,'sldId').map(el=>{
      const rid=el.getAttribute('r:id')||el.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');
      const rel=rels.get(rid);return rel?_zipNormalizePath('ppt/presentation.xml',rel.target):null;
    }).filter(n=>n&&zip.files[n]);
  }
  // Fallback for malformed decks.
  if(!slides.length)slides=Object.keys(zip.files).filter(n=>/^ppt\/slides\/slide\d+\.xml$/.test(n)).sort((a,b)=>parseInt(a.match(/slide(\d+)/)[1])-parseInt(b.match(/slide(\d+)/)[1]));
  if (!slides.length) throw new Error('No slides found in "' + file.name + '" — is it a valid .pptx?');
  let out = '';
  for (let i = 0; i < slides.length; i++) {
    const slidePath=slides[i];
    const body = _pptxRunText(await zip.files[slidePath].async('string'));
    const slideBase=slidePath.split('/').pop();
    const relPath='ppt/slides/_rels/'+slideBase+'.rels';
    let notes = '';
    if(zip.files[relPath]){
      const rels=_relsMap(await zip.files[relPath].async('string'));
      const noteRel=[...rels.values()].find(r=>/\/notesSlide$/i.test(r.type));
      const notesPath=noteRel?_zipNormalizePath(slidePath,noteRel.target):'';
      if(notesPath&&zip.files[notesPath]){
        const n=_pptxRunText(await zip.files[notesPath].async('string'));
        if(n.length)notes='\n[Speaker notes] '+n.join(' ');
      }
    }
    out += '\n--- SLIDE ' + (i + 1) + ' ---\n' + body.join('\n') + notes + '\n';
  }
  return out;
}





